using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Text;using System.Threading.Tasks;using System.Windows.Forms;
namespace Aster {
static class ToolCatalog {
 public static readonly string[][] Groups={new[]{"MONITORING","Session timeline","Performance compare","Performance alerts","Air Defense feed","Summary","Performance","Processes","Compact monitor","Insights","App history","Flight recorder"},new[]{"HARDWARE & NETWORK","CPU specs","GPU","Memory specs","Storage specs","Motherboard & BIOS","Network adapters","System info","Disk space","Network lab","Hardware report","Hardware compare"},new[]{"REPAIR & AI HELP","Diagnostics bundle","Update Aster","System check","Windows advisor","Recovery toolbox","Backup center","Help center","Startup apps","Services","Connections","Installed apps","Drivers","Users"},new[]{"PRODUCTIVITY","Maintenance planner","Command Center","Notebook","Checklist","Focus","Focus timer"},new[]{"APPEARANCE & PLAY","Video player","Themes","Theme studio","Home layout","Wallpaper studio","Playground","Preferences"}};
 public static string Hint(string name){switch(name){case "Session timeline":return "Session activity, personal markers and text export";case "Performance compare":return "Measure before and after using 20-sample windows";case "Maintenance planner":return "Recurring local reminders, completion and snooze";case "Command Center":return "Live status and shortcuts for your day";case "Performance alerts":return "Custom CPU and memory limits, sustained duration and cooldown";case "Diagnostics bundle":return "Preview and export a private aggregate support snapshot";case "Air Defense feed":return "Public advisories near you · Telegram alert monitor";case "Preferences":return "Startup animations, daily picture, greeting & settings";case "System check":return "Review resource pressure, storage space and power";case "Windows advisor":return "Investigate issues and prepare optional AI help";case "Backup center":return "Save and restore your Aster workspace";case "Network lab":return "Speed test, adapter details and saved results";default:return "Open "+name.ToLowerInvariant();}}
 public static bool Matches(string name,string query){return (name+" "+Hint(name)).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0;}
}
static class SystemReview {
 public static string SpaceStatus(long free,long total){if(total<=0)return "Unavailable";return (double)free/total<.1?"Low space — below 10%; review files before removing anything.":"At least 10% free.";}
 public static string Capture(Snapshot sample){var b=new StringBuilder("ASTER SYSTEM CHECK\r\nCaptured: "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"\r\n\r\n");if(sample==null)b.AppendLine("Live readings not yet available.");else{b.AppendLine("Sample time: "+sample.Time.ToString("yyyy-MM-dd HH:mm:ss"));b.AppendLine("CPU: "+sample.Cpu.ToString("F1")+"%"+(sample.Cpu>=90?" — high in this sample; check Processes.":""));b.AppendLine("Memory: "+sample.MemoryPercent.ToString("F1")+"%"+(sample.MemoryPercent>=85?" — review unneeded apps after saving work.":""));b.AppendLine("Available memory: "+Inventory.Bytes(sample.Available));}b.AppendLine("\r\nFIXED STORAGE");try{foreach(var drive in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed)){try{if(!drive.IsReady){b.AppendLine(drive.Name+" unavailable");continue;}long free=drive.AvailableFreeSpace,total=drive.TotalSize;b.AppendLine(drive.Name+"  "+Inventory.Bytes((ulong)free)+" available / "+Inventory.Bytes((ulong)total)+"  · "+SpaceStatus(free,total));}catch(Exception ex){b.AppendLine(drive.Name+" unavailable: "+ex.Message);}}}catch(Exception ex){b.AppendLine("Storage unavailable: "+ex.Message);}b.AppendLine("\r\nPOWER");try{var power=SystemInformation.PowerStatus;b.AppendLine("Power source: "+power.PowerLineStatus);var flag=power.BatteryChargeStatus;if(flag==BatteryChargeStatus.Unknown)b.AppendLine("Battery status unavailable.");else if((flag&BatteryChargeStatus.NoSystemBattery)!=0)b.AppendLine("No system battery reported.");else{float value=power.BatteryLifePercent;b.AppendLine(value>=0&&value<=1?"Battery: "+(value*100).ToString("F0")+"%":"Battery level unavailable.");}}catch{b.AppendLine("Power information unavailable.");}b.AppendLine("\r\nA snapshot, not a health certification. This does not scan Windows files, disk health, malware or updates. One high sample does not prove a fault. No changes were made.");return b.ToString();}
}
partial class MainWindow {
 readonly List<string> recentTools=new List<string>();
 void RememberTool(string name){AddSessionEvent("Opened "+name);if(name=="Tools hub")return;recentTools.Remove(name);recentTools.Insert(0,name);if(recentTools.Count>6)recentTools.RemoveAt(6);}
 string[][] NavigationGroups(string query){if(query.Length>0)return new[]{new[]{"SEARCH ALL TOOLS"}.Concat(buttons.Keys.Where(n=>ToolCatalog.Matches(n,query))).ToArray()};return new[]{new[]{"PINNED"}.Concat(preferences.Pins.Where(buttons.ContainsKey)).ToArray(),new[]{"MAIN","Command Center","Summary","Performance","Processes","Tools hub","System check"},new[]{"PERSONALIZE","Preferences","Update Aster"}};}
 void BuildToolsHub(){sub.Text="All your tools, neatly grouped · search or choose a category";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,46));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var filters=new FlowLayoutPanel{Dock=DockStyle.Fill};var find=new TextBox{Width=310,AccessibleName="Search all tools",Font=new Font("Segoe UI",12)};var category=new ComboBox{Width=250,DropDownStyle=ComboBoxStyle.DropDownList,AccessibleName="Tool category"};category.Items.Add("All categories");category.Items.AddRange(ToolCatalog.Groups.Select(g=>(object)g[0]).ToArray());category.SelectedIndex=0;filters.Controls.Add(new Label{Text="Find a tool",AutoSize=true,Margin=new Padding(0,7,12,0)});filters.Controls.Add(find);filters.Controls.Add(category);root.Controls.Add(filters,0,0);var recent=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=false};recent.Controls.Add(new Label{Text="RECENT",AutoSize=true,Margin=new Padding(0,10,12,0)});foreach(string item in recentTools){string target=item;var button=Button(item);button.Click+=(s,e)=>Navigate(target);recent.Controls.Add(button);}root.Controls.Add(recent,0,1);var sections=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};root.Controls.Add(sections,0,2);Action render=()=>{sections.SuspendLayout();foreach(Control c in sections.Controls.Cast<Control>().ToArray())c.Dispose();int count=0;foreach(var group in ToolCatalog.Groups){if(category.SelectedIndex>0&&(string)category.SelectedItem!=group[0])continue;var names=group.Skip(1).Where(n=>ToolCatalog.Matches(n,find.Text.Trim())).ToArray();if(names.Length==0)continue;sections.Controls.Add(new Label{Text=group[0],UseMnemonic=false,AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold),Margin=new Padding(3,18,0,10)});foreach(string name in names){string target=name;var row=new FlowLayoutPanel{Width=760,Height=47,WrapContents=false};var open=Button(name+"  →");open.AutoSize=false;open.Width=225;open.Height=38;open.TextAlign=ContentAlignment.MiddleLeft;open.Click+=(s,e)=>Navigate(target);row.Controls.Add(open);row.Controls.Add(new Label{Text=ToolCatalog.Hint(name),Width=430,Height=38,TextAlign=ContentAlignment.MiddleLeft});var pin=Button(preferences.Pins.Contains(name)?"★":"☆");pin.AccessibleName="Pin or unpin "+name;pin.Click+=(s,e)=>{if(preferences.Pins.Contains(target))preferences.Pins.Remove(target);else preferences.Pins.Add(target);SavePreferences();pin.Text=preferences.Pins.Contains(target)?"★":"☆";RebuildNavigation();};row.Controls.Add(pin);sections.Controls.Add(row);count++;}}if(count==0)sections.Controls.Add(new Label{Text="No tools match. Try another search or category.",AutoSize=true,Margin=new Padding(10)});sections.ResumeLayout();ApplyAppTheme();};find.TextChanged+=(s,e)=>render();category.SelectedIndexChanged+=(s,e)=>render();render();}
 void BuildSystemCheck(){sub.Text="Read-only review · refresh when needed · export or prepare help";var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var report=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Font=new Font("Segoe UI",11),Text="Reading storage and power…"};layout.Controls.Add(actions,0,0);layout.Controls.Add(report,0,1);var refresh=Button("Refresh check");var copy=Button("Copy report");var save=Button("Save report");var ai=Button("Prepare AI help");actions.Controls.AddRange(new Control[]{refresh,copy,save,ai});Action<bool> ready=value=>{copy.Enabled=save.Enabled=ai.Enabled=value;};Action capture=async()=>{ready(false);refresh.Enabled=false;try{var snapshot=current;string text=await Task.Run(()=>SystemReview.Capture(snapshot));if(!report.IsDisposed){report.Text=text;ready(true);}}catch(Exception ex){if(!report.IsDisposed)report.Text="Could not complete review: "+ex.Message;}finally{if(!refresh.IsDisposed)refresh.Enabled=true;}};refresh.Click+=(s,e)=>capture();copy.Click+=(s,e)=>{try{Clipboard.SetText(report.Text);}catch(Exception ex){MessageBox.Show(this,ex.Message);}};save.Click+=(s,e)=>{using(var dialog=new SaveFileDialog{Filter="Text report|*.txt",FileName="Aster-system-check.txt"})if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,report.Text);}catch(Exception ex){MessageBox.Show(this,ex.Message);}};ai.Click+=(s,e)=>{string evidence=report.Text;Navigate("Windows advisor");var advisor=content.Controls.OfType<AdvisorPanel>().FirstOrDefault();if(advisor!=null)advisor.PrepareEvidence(evidence);};capture();}
}
}
